---只执行一次的内容
function ShopUIView:Init()
    EventDelegate.Add(this.tabDailyEvent.onClick, EventDelegate.Callback(ShopUICtrl.TabDailyOnClick));
    EventDelegate.Add(this.tabRechargeEvent.onClick, EventDelegate.Callback(ShopUICtrl.TabRechargeOnClick));
    EventDelegate.Add(this.tabHotEvent.onClick, EventDelegate.Callback(ShopUICtrl.TabHotOnClick));
    EventDelegate.Add(this.tabDiscountEvent.onClick, EventDelegate.Callback(ShopUICtrl.TabDiscountOnClick));
    EventDelegate.Add(this.buttonCloseEvent.onClick, EventDelegate.Callback(ShopUICtrl.CloseOnClick));
    EventDelegate.Add(self.shopItemButtonBuyEvent.onClick, EventDelegate.Callback(ShopUICtrl.ItemPopupButtonBuyEventOnClick));
    EventDelegate.Add(self.shopItemPopupCloseEvent.onClick, EventDelegate.Callback(ShopUICtrl.ItemPopupCloseOnClick));

    table.insert(Player.MoneyChangeEvent, ShopUIView.RefreshUserMoney);

    --self.usedItemList = {};
    --self.recycledItemList = {};
    self.shopItemPopup:SetActive(false);
    self.cardDetailItem = DeckCardItem.new();
    self.cardDetailItem:InitPanel(self.shopItemPopupCardUIRoot)
end

