end

function ShopUIView.RefreshUserMoney()
    this.labelGoldCount.text = Player.GetGold();
    this.labelDiamondCount.text = Player.GetDiamond();
end

function ShopUIView:SWitchTab(tab)
    this.currentTab = tab;
    this.tabDaily.Press = false;
    this.tabRecharge.Press = false;
    this.tabHot.Press = false;
    this.tabDiscount.Press = false;
    if (tab == ShopTab.Daily) then
        this.tabDaily.Press = true;
    elseif (tab == ShopTab.Recharge) then
        this.tabRecharge.Press = true;
    elseif (tab == ShopTab.Hot) then
        this.tabHot.Press = true;
    elseif (tab == ShopTab.Discount) then
        this.tabDiscount.Press = true;
    end

    self:RefreshItems(tab);

    --老板娘
    self:RefreshBoss();
end

function ShopUIView:RefreshBoss()
    TextureSystem.Instance:LoadTexture2DX(bossTextureName[this.currentTab], TextureManager.TextureGroup.Card, function (texture2D)
        self.bossTexture.mainTexture = texture2D;
    end);

    local talkCount = tonumber(TextSystem.GetText(string.format("shop_talk_%d_count", this.currentTab)));
    if (talkCount == nil) then
        talkCount = 1;
    end
    local talkIndex = math.random(1, talkCount);
    self.labelBossTalk.text = TextSystem.GetText(string.format("shop_talk_%d_%d", this.currentTab, talkIndex));
end

function ShopUIView:RefreshItems(tab)
    local shopData = ShopUICtrl.Instance().shopData[tab];
    if (shopData ~= nil) then
        if (this.pageAndItem == nil) then
            this.pageAndItem = PageAndItem.new();
            this.pageAndItem:InitPanel(self.pageAndItemRoot);
        end
        this.pageAndItem:Construct(shopData, 6, ShopItem, tab);
    end
end

function ShopUIView:Update(deltaTime)
    if (this.pageAndItem ~= nil) then
        this.pageAndItem:Update();
    end
end

--详情窗口
function ShopUIView:ShowDetailWindow(shopItem)
    self.popedShopItem = shopItem;
    self.shopItemPopup:SetActive(true);

    if (shopItem.shopData.reward.type[1] == ItemType.Hero or
            shopItem.shopData.reward.type[1] == ItemType.Card) then
        self.shopItemPopupCardRoot:SetActive(true);
        self.shopItemPopupGoodsRoot:SetActive(false);

        if (shopItem.shopData.reward.type[1] == ItemType.Hero) then
            local hero = HeroManager.GetHero(shopItem.shopData.reward.id[1])
            self.cardDetailItem:SetItemHero(hero);
        else--if (data.type == ItemType.Card) then
            local card = CardManager.Card(shopItem.shopData.reward.id[1])
            self.cardDetailItem:SetItemCard(card);
        end
    else
        self.shopItemPopupCardRoot:SetActive(false);
        self.shopItemPopupGoodsRoot:SetActive(true);

        NGUITools.DestroyChildren(self.shopItemPopupGoodsIconRoot);
        self.mIconItem = ItemHelper.CreateAdaptedIconItem(shopItem.shopData.reward.type[1], shopItem.shopData.reward.id[1]);
        ItemHelper.GetIconItem(self.mIconItem, self.shopItemPopupGoodsIconRoot);
        self.shopItemPopupGoodsCount.text = "x" .. shopItem.shopData.reward.num[1];
        if (self.mIconItem:GetQuality() ~= nil) then
            self.shopItemPopupGoodsTary.spriteName = string.format("bag_icon0%d", self.mIconItem:GetQuality());
        else
            self.shopItemPopupGoodsTary.spriteName = "bag_icon02";
        end
    end

    self.shopItemPopupLabelName.text = shopItem.labelName.text;
    local goodsKey = "shop_goods_desc_" .. shopItem.shopData.id;
    local saleDesc = TextSystem.GetText(goodsKey)
    if (saleDesc ~= goodsKey) then
        self.shopItemPopupLabelDesc.text = saleDesc;
    else
        self.shopItemPopupLabelDesc.text = GameLogic.GetItemDescription(shopItem.shopData.reward.type[1], shopItem.shopData.reward.id[1]);
    end
    self.currencyImage.spriteName = shopItem.currencyImage.spriteName;

    local isRMB = (shopItem.shopData.currency == 1);
    self.labelRechargePrice.gameObject:SetActive(isRMB);
    self.labelItemPrice.gameObject:SetActive(not isRMB);
    self.currencyImage.gameObject:SetActive(not isRMB);
    if (shopItem.shopData.currency == 1) then
        self.labelRechargePrice.text = shopItem.labelRechargePrice.text;
    else
        if (shopItem.shopData.currency == 3) then
            self.currencyImage.spriteName = "gold";
        else
            self.currencyImage.spriteName = "diamond";
        end
        if (shopItem.shopData.discount ~= nil and shopItem.shopData.discount ~= 0) then
            self.labelItemPrice.text = shopItem.labelDiscountPrice.text;
        else
            self.labelItemPrice.text = shopItem.labelItemPrice.text;
        end
    end

    if (shopItem.shopData.limit ~= nil and shopItem.shopData.limit ~= 0) then--限量
        if (shopItem.shopData.buyLimit == shopItem.shopData.limit) then--已售罄
            self.labelSoldOut:SetActive(true);
            self.buttonBuy:SetActive(false);
        else
            self.labelSoldOut:SetActive(false);
            self.buttonBuy:SetActive(true);
        end
    end
end